import type { MatchStatus } from '../domain/match';
import { MATCH_STATUSES } from '../domain/match';
import type { BaselineComparison } from './baseline';
import type { CalibrationBin, StatusMatrix } from './metrics';
import type { EvalReport } from './run';

export interface EvalSection {
  readonly name: string;
  readonly report: EvalReport;
  /** The same cases through the lexical fallback alone; absent on the held-out section. */
  readonly baseline?: BaselineComparison;
}

const PREAMBLE = [
  'Generated by `pnpm run eval`. Every number below is limited evidence from a small',
  'hand-labeled set: it supports the design choices for this data, and it establishes',
  'neither calibration nor generalization to a catalog this one did not see.',
  '',
  'The personalized labels are circular by construction — a person wrote them looking at',
  'the same order history the algorithm reads, and there is no independent ground truth',
  'for what a customer meant. The mitigations are procedural: the labels were frozen',
  'before any parameter was tuned, each carries its reasoning, the held-out set stays',
  'untouched until the end, and constraint preservation is measured against the query',
  'itself rather than against any label. See `docs/eval/golden-rationale.md`.',
].join('\n');

const rate = (value: number): string => value.toFixed(3);

const plural = (count: number): string => (count === 1 ? '1 case' : `${String(count)} cases`);

const table = (header: readonly string[], rows: readonly (readonly string[])[]): string =>
  [
    `| ${header.join(' | ')} |`,
    `|${header.map(() => '---').join('|')}|`,
    ...rows.map((row) => `| ${row.join(' | ')} |`),
  ].join('\n');

const matrixRows = (matrix: StatusMatrix): string[][] =>
  MATCH_STATUSES.map((expected: MatchStatus) => [
    expected,
    ...MATCH_STATUSES.map((actual) => String(matrix[expected][actual])),
  ]);

const binRow = (bin: CalibrationBin): string[] => [
  `${bin.lower.toFixed(1)}–${bin.upper.toFixed(1)}`,
  String(bin.count),
  bin.precision === undefined ? '—' : rate(bin.precision),
];

/** Statuses a score gap has no way to produce, whatever the query reads like. */
const UNREACHABLE: readonly MatchStatus[] = ['history', 'unparsed'];

const casesExpecting = (matrix: StatusMatrix, statuses: readonly MatchStatus[]): number =>
  statuses.reduce(
    (total, expected) =>
      total + MATCH_STATUSES.reduce((row, actual) => row + matrix[expected][actual], 0),
    0,
  );

/** The evidence for ADR-001, and the one table where a number is not the parser's own.
 * docs/DESIGN.md 10.4. */
function comparison(report: EvalReport, baseline: BaselineComparison): string[] {
  const { retrieval, setRecovery, status } = report;

  return [
    '',
    '### Baseline comparison',
    '',
    [
      'The lexical fallback of `docs/DESIGN.md` 5.8 run alone over the same cases: token overlap',
      'over normalized descriptions, with no parse, no compatible set and no customer. It calls a',
      'query unique when the runner-up trails the best hit by more than the configured gap, so',
      '`history` and `unparsed` are statuses it cannot produce at all — cases expecting one of',
      `those two: ${String(casesExpecting(status.matrix, UNREACHABLE))} of ${String(status.cases)}.`,
      'Its set recovery is scored on as many top hits as the labeled set holds, the size of the',
      'answer handed to it for free, because it ranks every row a query token reaches and has no',
      'compatible set to cut.',
    ].join('\n'),
    '',
    table(
      ['metric', 'parser', 'baseline', 'cases'],
      [
        ['Hit@1', rate(retrieval.hit1), rate(baseline.retrieval.hit1), String(retrieval.cases)],
        ['Hit@3', rate(retrieval.hit3), rate(baseline.retrieval.hit3), String(retrieval.cases)],
        ['MRR', rate(retrieval.mrr), rate(baseline.retrieval.mrr), String(retrieval.cases)],
        [
          'Set precision',
          rate(setRecovery.precision),
          rate(baseline.setRecovery.precision),
          String(setRecovery.cases),
        ],
        [
          'Set recall',
          rate(setRecovery.recall),
          rate(baseline.setRecovery.recall),
          String(setRecovery.cases),
        ],
        [
          'Exact-set rate',
          rate(setRecovery.exactSetRate),
          rate(baseline.setRecovery.exactSetRate),
          String(setRecovery.cases),
        ],
        [
          'Status accuracy',
          rate(status.accuracy),
          rate(baseline.status.accuracy),
          String(status.cases),
        ],
      ],
    ),
    '',
    'Where the baseline puts each status, against the same expectations:',
    '',
    table(['expected \\ actual', ...MATCH_STATUSES], matrixRows(baseline.status.matrix)),
  ];
}

function section({ name, report, baseline }: EvalSection): string {
  const { retrieval, setRecovery, status, constraints, personalization, calibration } = report;

  return [
    `## ${name}`,
    '',
    `${plural(report.cases)} in this set.`,
    '',
    `### Retrieval of the intended SKU (${plural(retrieval.cases)})`,
    '',
    table(
      ['metric', 'value'],
      [
        ['Hit@1', rate(retrieval.hit1)],
        ['Hit@3', rate(retrieval.hit3)],
        ['MRR', rate(retrieval.mrr)],
      ],
    ),
    '',
    `### Recovery of the compatible set (${plural(setRecovery.cases)})`,
    '',
    table(
      ['metric', 'value'],
      [
        ['Set precision', rate(setRecovery.precision)],
        ['Set recall', rate(setRecovery.recall)],
        ['Exact-set rate', rate(setRecovery.exactSetRate)],
      ],
    ),
    '',
    `### Status correctness (${plural(status.cases)})`,
    '',
    `Accuracy ${rate(status.accuracy)}.`,
    '',
    table(['expected \\ actual', ...MATCH_STATUSES], matrixRows(status.matrix)),
    '',
    `### Constraint preservation (${plural(constraints.cases)})`,
    '',
    `${String(constraints.violations)} of the matches returned, with and without a customer, contradict an attribute the query asked for.`,
    ...(constraints.offenders.length === 0
      ? []
      : [
          '',
          table(
            ['case', 'sku', 'attribute'],
            constraints.offenders.map((offender) => [
              offender.id,
              offender.sku,
              offender.attribute,
            ]),
          ),
        ]),
    '',
    `### Personalization (${plural(personalization.cases)})`,
    '',
    table(
      ['metric', 'value', 'cases'],
      [
        // Its own denominator too: a personalized case whose label names no single intended
        // SKU cannot be scored by any answer, so it is out of both rates rather than a miss.
        ['Hit@1 with the customer', rate(personalization.hit1), String(personalization.hit1Cases)],
        [
          'Hit@1 without the customer',
          rate(personalization.hit1WithoutCustomer),
          String(personalization.hit1Cases),
        ],
        // Its own denominator: a case answered with one result has no second to measure
        // against, so this mean covers fewer cases than the heading.
        [
          'Mean top-1 to top-2 margin',
          rate(personalization.margin),
          String(personalization.marginCases),
        ],
      ],
    ),
    '',
    `### Calibration (${plural(calibration.cases)})`,
    '',
    table(['top-1 confidence', 'cases', 'empirical top-1 precision'], calibration.bins.map(binRow)),
    '',
    `### Latency (${plural(report.latency.cases)})`,
    '',
    'Measured at the limit the API serves, and the one number here that moves between runs.',
    '',
    table(
      ['percentile', 'ms'],
      [
        ['p50', report.latency.p50.toFixed(1)],
        ['p95', report.latency.p95.toFixed(1)],
      ],
    ),
    ...(baseline === undefined ? [] : comparison(report, baseline)),
  ].join('\n');
}

export function toMarkdown(
  sections: readonly EvalSection[],
  title = '# Evaluation report',
): string {
  return [title, '', PREAMBLE, '', ...sections.map(section)].join('\n') + '\n';
}

const round = (value: number): number => Number(value.toFixed(4));

export interface JsonSection {
  name: string;
  cases: number;
  retrieval: { cases: number; hit1: number; hit3: number; mrr: number };
  setRecovery: { cases: number; precision: number; recall: number; exactSetRate: number };
  status: { cases: number; accuracy: number; matrix: StatusMatrix };
  constraints: { cases: number; violations: number };
  personalization: {
    cases: number;
    hit1Cases: number;
    hit1: number;
    hit1WithoutCustomer: number;
    margin: number;
    marginCases: number;
  };
  calibration: { cases: number; bins: CalibrationBin[] };
}

export interface JsonSummary {
  sections: JsonSection[];
}

/** The committed record the CI gate of PRG-36 compares against. Latency is deliberately
 * absent: it moves between runs on identical inputs, so a gate over it would fail on a
 * slower machine rather than on a regression. */
export function toJson(sections: readonly EvalSection[]): JsonSummary {
  return {
    sections: sections.map(({ name, report }) => ({
      name,
      cases: report.cases,
      retrieval: {
        cases: report.retrieval.cases,
        hit1: round(report.retrieval.hit1),
        hit3: round(report.retrieval.hit3),
        mrr: round(report.retrieval.mrr),
      },
      setRecovery: {
        cases: report.setRecovery.cases,
        precision: round(report.setRecovery.precision),
        recall: round(report.setRecovery.recall),
        exactSetRate: round(report.setRecovery.exactSetRate),
      },
      status: {
        cases: report.status.cases,
        accuracy: round(report.status.accuracy),
        matrix: report.status.matrix,
      },
      constraints: { cases: report.constraints.cases, violations: report.constraints.violations },
      personalization: {
        cases: report.personalization.cases,
        hit1Cases: report.personalization.hit1Cases,
        hit1: round(report.personalization.hit1),
        hit1WithoutCustomer: round(report.personalization.hit1WithoutCustomer),
        margin: round(report.personalization.margin),
        marginCases: report.personalization.marginCases,
      },
      calibration: {
        cases: report.calibration.cases,
        bins: report.calibration.bins.map((bin) => ({
          ...bin,
          precision: bin.precision === undefined ? undefined : round(bin.precision),
        })),
      },
    })),
  };
}
